css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: A4 portrait;
  margin: 0;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  padding: 0 !important;
}

.cd-receipt, .cd-receipt * { box-sizing: border-box; }
.cd-receipt { position: relative; width: 210mm; height: 297mm; overflow: hidden; color: #333; background: #fff; font-family: "TH Sarabun Document", sans-serif; font-size: 3.7mm; line-height: 1.05; }
.cd-receipt small { display: block; font-size: 2.6mm; font-weight: 400; line-height: 1; }
.cd-receipt .document-header { position: relative; height: 55mm; }
.cd-receipt .company-logo { position: absolute; top: 15mm; left: 12mm; width: 22mm; height: 10mm; object-fit: contain; }
.cd-receipt .company-info { position: absolute; top: 12mm; left: 37mm; width: 115mm; }
.cd-receipt .company-info strong { display: block; font-size: 5.5mm; font-weight: 400; }
.cd-receipt .company-info span { display: block; margin-top: 2mm; }
.cd-receipt h1 { position: absolute; top: 35mm; right: 16mm; width: 61mm; margin: 0; padding: 1mm; border-radius: 5mm; background: #9fc5eb; font-size: 6mm; text-align: center; }
.cd-receipt h2 { position: absolute; top: 48mm; right: 25mm; margin: 0; font-size: 4.5mm; }
.cd-receipt .receipt-info { display: grid; grid-template-columns: 52% 48%; width: 182mm; height: 39mm; margin: 0 14mm 1mm; }
.cd-receipt .customer-panel, .cd-receipt .document-panel { position: relative; padding: 3mm 4mm; border: 0.25mm solid #333; border-radius: 2.5mm; }
.cd-receipt .customer-panel { margin-right: 2mm; }
.cd-receipt .customer-code { position: absolute; top: 3mm; left: 23mm; }
.cd-receipt .customer { margin-top: 3mm; height: 26mm; overflow: hidden; }
.cd-receipt .document-panel dl { display: grid; grid-template-columns: 38mm 1fr; grid-auto-rows: 11mm; margin: 0; }
.cd-receipt .document-panel dt, .cd-receipt .document-panel dd { margin: 0; }
.cd-receipt .references-section { width: 182mm; height: 129mm; margin: 0 14mm; }
.cd-receipt table { width: 100%; height: 100%; border-collapse: separate; border-spacing: 0; table-layout: fixed; border: 0.25mm solid #333; border-radius: 2.5mm 2.5mm 0 0; overflow: hidden; }
.cd-receipt th, .cd-receipt td { padding: 1.2mm; border-right: 0.25mm solid #333; }
.cd-receipt th:last-child, .cd-receipt td:last-child { border-right: 0; }
.cd-receipt th { height: 11mm; border-bottom: 0.25mm solid #333; font-weight: 400; text-align: center; }
.cd-receipt td { vertical-align: top; }
.cd-receipt td:not(:nth-child(2)) { text-align: center; }
.cd-receipt td:nth-child(n+5) { text-align: right; }
.cd-receipt col.no { width: 5.5%; } .cd-receipt col.invoice { width: 19.5%; } .cd-receipt col.date { width: 12.5%; } .cd-receipt col.due { width: 12.5%; } .cd-receipt col.amount { width: 16%; } .cd-receipt col.remain { width: 17%; } .cd-receipt col.paid { width: 17%; }
.cd-receipt .receipt-total { display: grid; grid-template-columns: 63% 22% 15%; align-items: center; width: 182mm; height: 11mm; margin: 0 14mm; border: 0.25mm solid #333; border-top: 0; }
.cd-receipt .receipt-total > * { height: 100%; padding: 2mm; border-right: 0.25mm solid #333; }
.cd-receipt .receipt-total > :last-child { border-right: 0; text-align: right; }
.cd-receipt .payment-section { display: grid; grid-template-columns: 66% 34%; width: 182mm; height: 51mm; margin: 0 14mm; border: 0.25mm solid #333; border-top: 0; border-radius: 0 0 2.5mm 2.5mm; }
.cd-receipt .payment-detail, .cd-receipt .authorization { position: relative; padding: 3mm; }
.cd-receipt .payment-detail { border-right: 0.25mm solid #333; }
.cd-receipt .payment-detail p { margin: 0; font-size: 2.5mm; }
.cd-receipt .payment-method { margin: 4mm 0 0 57mm; white-space: nowrap; }
.cd-receipt .collector-line { position: absolute; right: 3mm; bottom: 8mm; }
.cd-receipt .collector-caption { position: absolute; right: 3mm; bottom: 3mm; }
.cd-receipt .authorization { text-align: center; }
.cd-receipt .authorized-line, .cd-receipt .prepared-line { margin: 16mm 3mm 2mm; border-bottom: 0.2mm solid #555; }
.cd-receipt .prepared-line { margin-top: 10mm; }
.cd-receipt .prepared { position: absolute; left: 2mm; right: 2mm; bottom: 8mm; font-size: 2.6mm; }
